Lemma xcl_flag : forall LBx (SP : Z) Xc XS' (m1 : mem),
  as_RFS H ((1, ff, fp) :: LF) m1 -> Forall (fs_scratch H ((1, ff, fp) :: LF)) XS' ->
  Forall (fun iv : Z * Z => fp + 1 <= fst iv \/ snd iv <= fp) Xc ->
  xclient_range H LBx SP (Xc ++ XS') fp 1.
Proof.
  open_X. intros LBx SP Xc XS' m1 RF FXS FXc. split; [eapply (fp_client_range H); exact FF|].
  apply Forall_app. split; [exact FXc|]. exact (live_flag_off_scratch H HH _ _ _ _ _ _ RF FXS).
Qed.

